let calls = 0;
function f(n) {
  calls++;
  if (n <= 2) return n;
  return f(n - 1) + f(n - 2);
}
console.log(f(30), calls);  // 832040,  约 2.7 百万次

let calls = 0;
const memo = {};
function f(n) {
  calls++;
  if (n <= 2) return n;
  if (memo[n]) return memo[n];
  return (memo[n] = f(n - 1) + f(n - 2));
}
console.log(f(30), calls);  // 832040, 57 次

function climb(n) {
  let a = 1, b = 2;
  for (let i = 3; i <= n; i++) [a, b] = [b, a + b];
  return n <= 2 ? n : b;
}
