const express = require('express');
const app = express();
app.use(express.json());

let todos = [{ id: 1, text: '买牛奶', done: false }];
app.listen(3001, () => console.log('API on :3001'));

app.get('/todos', (req, res) => res.json(todos));

app.post('/todos', (req, res) => {
  const t = { id: Date.now(), text: req.body.text, done: false };
  todos.push(t);
  res.status(201).json(t);
});

app.patch('/todos/:id', (req, res) => {
  const t = todos.find(x => x.id == req.params.id);
  if (!t) return res.status(404).json({ error: 'not found' });
  Object.assign(t, req.body);
  res.json(t);
});

app.delete('/todos/:id', (req, res) => {
  todos = todos.filter(x => x.id != req.params.id);
  res.status(204).end();
});

const primary = new Map();
const replica = new Map();

function write(key, val) {
  primary.set(key, val);
  setTimeout(() => replica.set(key, val), 500);   // 复制延迟
}
function readFrom(type, key) {
  return (type === 'primary' ? primary : replica).get(key);
}

