function entropy(ps) {
  return -ps.reduce((s, p) =>
    p === 0 ? s : s + p * Math.log2(p), 0);
}
console.log(entropy([0.5, 0.5]));        // 1 bit
console.log(entropy([0.9, 0.1]));        // ≈0.469 bit
console.log(entropy([1, 0]));            // 0 bit

function textEntropy(text) {
  const freq = {};
  for (const ch of text) freq[ch] = (freq[ch] || 0) + 1;
  const ps = Object.values(freq).map(c => c / text.length);
  return entropy(ps);
}
console.log(textEntropy("哈哈哈哈哈哈"));        // 低
console.log(textEntropy("信息熵度量不确定性"));   // 高

